select cleared_before_id
from t_conversation_clear
where username = #{username,jdbcType=VARCHAR}
  and peer = #{peer,jdbcType=VARCHAR}

select cleared_before_id as clearedBeforeId,
       updated_at as updatedAt
from t_conversation_clear
where username = #{username,jdbcType=VARCHAR}
  and peer = #{peer,jdbcType=VARCHAR}

mapper.update:
update t_conversation_clear
set cleared_before_id = greatest(cleared_before_id, #{clearedBeforeId,jdbcType=BIGINT}),
    updated_at = #{updatedAt,jdbcType=BIGINT}
where username = #{username,jdbcType=VARCHAR}
  and peer = #{peer,jdbcType=VARCHAR}
